window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4525095bfb67fc94"]={"versions": [{"id": "FIG-4525095bfb67fc94", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Dateidiagramm bzw. Dateistrukturdiagramm zur Darstellung der statischen Inklusionsbeziehungen (<code>#include</code>) und Datei-Abhängigkeiten des Basic Software (BSW) Schedulers (<code>SchM</code>) innerhalb der AUTOSAR-Basissoftwarearchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst C-Quell- und Header-Dateien sowie deren gerichtete Inklusionsabhängigkeiten (Stereotyp <code>«includes»</code>):</p>\n<ul class=\"fig-list\"><li><code>SchM.c</code>: Zentrale Implementierungsdatei des BSW Schedulers.\n</li><li><code>SchM.h</code>: Haupt-Header des BSW Schedulers, inkludiert von <code>SchM.c</code>.\n</li><li><code>SchM_cfg.h</code>: Konfigurations-Header des BSW Schedulers, inkludiert von <code>SchM.c</code>.\n</li><li><code>&lt;ModulePrefix&gt;.h</code>: Modul-spezifische Header der BSW-Module mit Kardinalität <code>1..*</code> und Rollenbezeichnung <code>+modules</code>, inkludiert von <code>SchM.c</code>.\n</li><li><code>SchM_&lt;ModulePrefix&gt;.h</code>: Modulspezifische Scheduler-Header mit Kardinalität <code>1..*</code> und Rollenbezeichnung <code>+modules</code>, inkludiert von <code>SchM.c</code>.\n</li><li><code>Det.h</code>: Header des Default Error Tracers, inkludiert von <code>SchM.c</code> mit Kardinalität <code>0..1</code>, annotiert durch eine Bedingungsnotiz („if development error detection is turned on“).\n</li><li><code>Std_Types.h</code>: Standard-Typdefinitionen, inkludiert von <code>SchM.h</code>.\n</li><li><code>Compiler.h</code>: Compiler-Abstraktions-Header, inkludiert von <code>Std_Types.h</code>.\n</li><li><code>Platform_Types.h</code>: Plattformspezifische Basisdatentypen, inkludiert von <code>Std_Types.h</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusions- und Kompilierzeit-Abhängigkeitsmodell; kein dynamischer Ablauf oder Nachrichtenaustausch zur Laufzeit dargestellt. Die Beziehungen definieren die hierarchische Einbindung von Symbolen, Typen und Schnittstellen während des Präprozessor- und Übersetzungsvorgangs.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Inklusionshierarchie definiert die Kopplung und Trennung von Konfiguration (<code>SchM_cfg.h</code>), Modulabstraktionen (<code>SchM_&lt;ModulePrefix&gt;.h</code>, <code>&lt;ModulePrefix&gt;.h</code>) und Infrastrukturtypen (<code>Std_Types.h</code>, <code>Compiler.h</code>, <code>Platform_Types.h</code>). Die Einbindung von <code>Det.h</code> ist optional und streng an die Aktivierung der Entwicklungstrace- und Fehlererkennung gebunden. Für jedes integrierte BSW-Modul müssen die entsprechenden modulspezifischen Header mit der Kardinalität <code>1..*</code> bereitgestellt und eingebunden werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-bc9bad3d26d9f1da", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Dateidiagramm bzw. Dateistrukturdiagramm zur Darstellung der statischen Inklusionsbeziehungen (<code>#include</code>) und Datei-Abhängigkeiten des Basic Software (BSW) Schedulers (<code>SchM</code>) innerhalb der AUTOSAR-Basissoftwarearchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst C-Quell- und Header-Dateien sowie deren gerichtete Inklusionsabhängigkeiten (Stereotyp <code>«includes»</code>):</p>\n<ul class=\"fig-list\"><li><code>SchM.c</code>: Zentrale Implementierungsdatei des BSW Schedulers.\n</li><li><code>SchM.h</code>: Haupt-Header des BSW Schedulers, inkludiert von <code>SchM.c</code>.\n</li><li><code>SchM_cfg.h</code>: Konfigurations-Header des BSW Schedulers, inkludiert von <code>SchM.c</code>.\n</li><li><code>&lt;ModulePrefix&gt;.h</code>: Modul-spezifische Header der BSW-Module mit Kardinalität <code>1..*</code> und Rollenbezeichnung <code>+modules</code>, inkludiert von <code>SchM.c</code>.\n</li><li><code>SchM_&lt;ModulePrefix&gt;.h</code>: Modulspezifische Scheduler-Header mit Kardinalität <code>1..*</code> und Rollenbezeichnung <code>+modules</code>, inkludiert von <code>SchM.c</code>.\n</li><li><code>Det.h</code>: Header des Default Error Tracers, inkludiert von <code>SchM.c</code> mit Kardinalität <code>0..1</code>, annotiert durch eine Bedingungsnotiz („if development error detection is turned on“).\n</li><li><code>Std_Types.h</code>: Standard-Typdefinitionen, inkludiert von <code>SchM.h</code>.\n</li><li><code>Compiler.h</code>: Compiler-Abstraktions-Header, inkludiert von <code>Std_Types.h</code>.\n</li><li><code>Platform_Types.h</code>: Plattformspezifische Basisdatentypen, inkludiert von <code>Std_Types.h</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusions- und Kompilierzeit-Abhängigkeitsmodell; kein dynamischer Ablauf oder Nachrichtenaustausch zur Laufzeit dargestellt. Die Beziehungen definieren die hierarchische Einbindung von Symbolen, Typen und Schnittstellen während des Präprozessor- und Übersetzungsvorgangs.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Inklusionshierarchie definiert die Kopplung und Trennung von Konfiguration (<code>SchM_cfg.h</code>), Modulabstraktionen (<code>SchM_&lt;ModulePrefix&gt;.h</code>, <code>&lt;ModulePrefix&gt;.h</code>) und Infrastrukturtypen (<code>Std_Types.h</code>, <code>Compiler.h</code>, <code>Platform_Types.h</code>). Die Einbindung von <code>Det.h</code> ist optional und streng an die Aktivierung der Entwicklungstrace- und Fehlererkennung gebunden. Für jedes integrierte BSW-Modul müssen die entsprechenden modulspezifischen Header mit der Kardinalität <code>1..*</code> bereitgestellt und eingebunden werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-4525095bfb67fc94", "to": "FIG-bc9bad3d26d9f1da", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
